                  "attrs": {}
                }
              ]
            },
            {
              "text": " Brain retrieval ranks results by relevance alone. Older decisions and facts surface indefinitely even after newer ones supersede them, because the ranking system has no mechanism to express that fresher information should be preferred in near-tie scenarios.",
              "type": "text"
            }
          ]
        },
        {
          "type": "paragraph",
          "content": [
            {
              "text": "Solution:",
              "type": "text",
              "marks": [
                {
                  "type": "bold",
                  "attrs": {}
                }
              ]
            },
            {
              "text": " Introduced time-weighted ranking as an opt-in feature in retrieval. A new ",
              "type": "text"
            },
            {
              "text": "recency",
              "type": "text",
              "marks": [
                {
                  "type": "code",
                  "attrs": {}
                }
              ]
            },
            {
              "text": " module applies a deterministic multiplier to fused scores that decays from 1.5× for fresh records to 0.3× for ancient ones, with a 90-day half-life. The multiplier:",
              "type": "text"
            }
          ]
        },
        {
          "type": "bulletList",
          "content": [
            {
              "type": "listItem",
              "content": [
                {
                  "type": "paragraph",
                  "content": [
                    {
                      "text": "Reorders results on near-ties without filtering or dropping anything",
                      "type": "text"
                    }
                  ]
                }
              ]
            },
            {
              "type": "listItem",
              "content": [
                {
                  "type": "paragraph",
                  "content": [
                    {
                      "text": "Never overwhelms relevance (5× spread ensures stronger matches win regardless of age)",
                      "type": "text"
                    }
                  ]
                }
              ]
            },
            {
              "type": "listItem",
              "content": [
                {
                  "type": "paragraph",
                  "content": [
                    {
                      "text": "Leaves undated records neutral (1.0×) rather than demoting them",
                      "type": "text"
                    }
                  ]
                }
              ]
            },
            {
              "type": "listItem",
              "content": [
                {
                  "type": "paragraph",
                  "content": [
                    {
                      "text": "Works only when explicitly enabled via ",
                      "type": "text"
                    },
                    {
                      "text": "retrievalOptions.Recency",
                      "type": "text",
                      "marks": [
                        {
                          "type": "code",
