  "phase": "reviewing",
  "bodyDocument": {
    "id": "01M3249YFDAMVEZ51WJB6RGWGJ",
    "documentKey": "trail:01M3249YEXJB7GT9TH73M0F7EP:body",
    "schemaVersion": 1,
    "contentJson": {
      "type": "doc",
      "content": [
        {
          "type": "paragraph",
          "content": [
            {
              "text": "Problem:",
              "type": "text",
              "marks": [
                {
                  "type": "bold",
                  "attrs": {}
                }
              ]
            },
            {
              "text": " Brain retrieval ranks results by relevance alone. Older decisions and facts surface indefinitely even after newer ones supersede them, because the ranking system has no mechanism to express that fresher information should be preferred in near-tie scenarios.",
              "type": "text"
            }
          ]
        },
        {
          "type": "paragraph",
          "content": [
            {
              "text": "Solution:",
              "type": "text",
              "marks": [
                {
                  "type": "bold",
                  "attrs": {}
                }
              ]
            },
            {
              "text": " Introduced time-weighted ranking as an opt-in feature in retrieval. A new ",
              "type": "text"
            },
            {
              "text": "recency",
              "type": "text",
              "marks": [
                {
                  "type": "code",
                  "attrs": {}
                }
              ]
            },
            {
              "text": " module applies a deterministic multiplier to fused scores that decays from 1.5× for fresh records to 0.3× for ancient ones, with a 90-day half-life. The multiplier:",
              "type": "text"
            }
          ]
        },
        {
          "type": "bulletList",
          "content": [
