 runner := semanticFixtureRunner(repoDir, semanticFixtureSnapshot("1.0"))
 opts := Options{Version: "test", Env: env, Runner: runner}
 storage, err := repoStoragePaths(context.Background(), runner, env, repoDir)
 if err != nil { t.Fatal(err) }
 now := time.Now().UTC()
 facts := []factRecord{
  {ID: "fact:old", Text: "alpha beta retrieval", Branch: "feature", Status: factStatusActive, UpdatedAt: now.Add(-3*365*24*time.Hour)},
  {ID: "fact:fresh", Text: "alpha retrieval", Branch: "feature", Status: factStatusActive, UpdatedAt: now.Add(-24*time.Hour)},
 }
 if err := writeFacts(storage.BrainDir, "feature", facts); err != nil { t.Fatal(err) }
 for _, enabled := range []bool{false,true} {
  want := "fact:old"
  if enabled { want = "fact:fresh" }
  for _, verb := range []string{"query", "search"} {
   args := []string{verb,"alpha beta","--source","fact","--limit","1","--json"}
   if verb == "query" { args = append(args,"--keyword") }
   if enabled { args = append(args,"--recency","--recency-half-life","720h") }
   out, err := execute(t,NewRootCommand(opts),args...)
   if err != nil { t.Fatal(err) }
