		// regardless of when it was first written, and revision is exactly
		// the signal recency weighting should follow.
		if !f.UpdatedAt.IsZero() {
			out[i].CreatedAt = f.UpdatedAt.UTC().Format(time.RFC3339)
		}
	}
	return out
}

